import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D9E58p8B.js";const m=JSON.parse('{"title":"Getting started","description":"","frontmatter":{"title":"Getting started"},"headers":[],"relativePath":"en/agent/demarrer.md","filePath":"en/agent/demarrer.md"}'),s={name:"en/agent/demarrer.md"};function i(r,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Before a first task, ask the agent to check that everything is in place. A single call is enough.</p><h2 id="what-you-ask" tabindex="-1">What you ask <a class="header-anchor" href="#what-you-ask" aria-label="Permalink to &quot;What you ask&quot;">​</a></h2><blockquote><p>&quot;Check that Daimon is ready.&quot;</p></blockquote><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><p>It calls <a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>, with no parameters. The tool probes the permissions with APIs that never open a dialog, then returns the state of each organ. It can also call <a href="/Daimon/en/reference/diagnostic.html#ping"><code>ping</code></a>, which answers <code>pong</code> and only proves that the server responds.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>A readable report in the conversation. The keys the agent reads:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it says</th></tr></thead><tbody><tr><td><code>ok</code></td><td>The overall verdict</td></tr><tr><td><code>permissions</code></td><td>Screen Recording and Accessibility: granted or not</td></tr><tr><td><code>organs</code></td><td>The state of Vue (Sight), Touché (Touch) and Mains (Hands), and what it is based on</td></tr><tr><td><code>ceiling</code></td><td>The active ceiling</td></tr><tr><td><code>consequences</code></td><td>What each missing permission concretely changes for each tool</td></tr><tr><td><code>next</code></td><td>The suggested next steps</td></tr></tbody></table><h2 id="if-something-is-missing" tabindex="-1">If something is missing <a class="header-anchor" href="#if-something-is-missing" aria-label="Permalink to &quot;If something is missing&quot;">​</a></h2><ul><li><strong>A permission is missing</strong>: <code>consequences</code> says which tools are affected. Grant it in the system settings: <a href="/Daimon/en/guide/autorisations.html">Permissions</a>.</li><li><strong>The agent sees no Daimon tool</strong>: Daimon is not registered in this agent, or the agent has not been restarted. See <a href="/Daimon/en/guide/clients-mcp.html">AI clients</a>.</li><li><strong>The ceiling is at L0</strong>: this is the default setting. The agent will look but not act: see <a href="/Daimon/en/agent/agir.html">Acting</a>.</li></ul><p>Next: <a href="/Daimon/en/agent/regarder.html">Looking at the screen</a>.</p>',12)])])}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
